static int 
dtb_proj_proj_main_create(
    DtbProjProjMainInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Display	*display= (parent == NULL? NULL:XtDisplay(parent));
    String	icon_name_str = NULL;
    String	title_str = NULL;
    
    if (instance->proj_main == NULL) {
        icon_name_str = XtNewString(CATGETS(Dtb_project_catd, 10, 1, "Project Organizer"));
        title_str = XtNewString(CATGETS(Dtb_project_catd, 10, 1, "Project Organizer"));
        instance->proj_main =
            XtVaCreatePopupShell("proj_main",
                topLevelShellWidgetClass,
                parent,
                XmNallowShellResize, True,
                XmNtitle, title_str,
                XmNiconName, icon_name_str,
                XmNinitialState, NormalState,
                XmNbackground, dtb_cvt_string_to_pixel(parent, "white"),
                NULL);
        XtFree(title_str);
        title_str = NULL;
        XtFree(icon_name_str);
        icon_name_str = NULL;
    }
    if (instance->proj_main == NULL)
        return -1;

    if (instance->proj_main_mainwin == NULL) {
        instance->proj_main_mainwin =
            XtVaCreateWidget("dtb_proj_proj_main_mainwin",
                xmMainWindowWidgetClass,
                instance->proj_main,
                XmNbackground, dtb_cvt_string_to_pixel(instance->proj_main, "white"),
                NULL);
    }
    if (instance->proj_main_mainwin == NULL)
        return -1;

    if (instance->proj_main_form == NULL) {
        instance->proj_main_form =
            XtVaCreateWidget("proj_main_form",
                xmFormWidgetClass,
                instance->proj_main_mainwin,
                XmNmarginHeight, 0,
                XmNmarginWidth, 0,
                XmNresizePolicy, XmRESIZE_ANY,
                XmNbackground, dtb_cvt_string_to_pixel(instance->proj_main_mainwin, "white"),
                NULL);
    }
    if (instance->proj_main_form == NULL)
        return -1;

    
    /*
     * Call user (Post-)Create procs
     */
    projP_set_userdata(instance->proj_main, (XtPointer)NULL, (XtPointer)instance);
    return 0;
}



static int 
dtb_proj_menubar_create(
    DtbProjProjMainInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    Arg	args[7];	/* need 2 args (add 5 to be safe) */
    int	n = 0;
    
    if (instance->menubar == NULL) {
        n = 0;
        XtSetArg(args[n], XmNrowColumnType, XmMENU_BAR);  ++n;
        instance->menubar =
            XmCreateMenuBar(parent,
                "menubar", args, n);
    }
    if (instance->menubar == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 10, 27, "Project"));
    if (instance->menubar_items.Project_item == NULL) {
        instance->menubar_items.Project_item =
            XtVaCreateManagedWidget("Project_item",
                xmCascadeButtonWidgetClass,
                instance->menubar,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->menubar_items.Project_item == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 10, 28, "Module"));
    if (instance->menubar_items.Module_item == NULL) {
        instance->menubar_items.Module_item =
            XtVaCreateManagedWidget("Module_item",
                xmCascadeButtonWidgetClass,
                instance->menubar,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->menubar_items.Module_item == NULL)
        return -1;

    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 10, 29, "Help"));
    if (instance->menubar_items.Help_item == NULL) {
        instance->menubar_items.Help_item =
            XtVaCreateManagedWidget("Help_item",
                xmCascadeButtonWidgetClass,
                instance->menubar,
                XmNlabelString, label_xmstring,
                NULL);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->menubar_items.Help_item == NULL)
        return -1;

    return 0;
}



