static int 
dtb_proj_module_drawarea_create(
    DtbProjProjMainInfo instance,
    Widget parent
)
{
    Arg	args[21];	/* need 16 args (add 5 to be safe) */
    int	n = 0;
    
    if (instance->module_drawarea_scrolledwin == NULL) {
        n = 0;
        XtSetArg(args[n], XmNbottomOffset, -1);  ++n;
        XtSetArg(args[n], XmNbottomAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNrightOffset, -1);  ++n;
        XtSetArg(args[n], XmNrightAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNleftOffset, 0);  ++n;
        XtSetArg(args[n], XmNleftAttachment, XmATTACH_FORM);  ++n;
        XtSetArg(args[n], XmNtopOffset, 0);  ++n;
        XtSetArg(args[n], XmNtopAttachment, XmATTACH_WIDGET);  ++n;
        XtSetArg(args[n], XmNscrollBarDisplayPolicy, XmAPPLICATION_DEFINED);  ++n;
        XtSetArg(args[n], XmNspacing, 0);  ++n;
        XtSetArg(args[n], XmNscrollingPolicy, XmAUTOMATIC);  ++n;
        XtSetArg(args[n], XmNheight, 131);  ++n;
        XtSetArg(args[n], XmNwidth, 419);  ++n;
        XtSetArg(args[n], XmNy, 46);  ++n;
        XtSetArg(args[n], XmNx, 0);  ++n;
        instance->module_drawarea_scrolledwin =
            XmCreateScrolledWindow(parent,
                "module_drawarea_scrolledwin", args, n);
    }
    if (instance->module_drawarea_scrolledwin == NULL)
        return -1;

    if (instance->module_drawarea == NULL) {
        instance->module_drawarea =
            XtVaCreateWidget("module_drawarea",
                xmDrawingAreaWidgetClass,
                instance->module_drawarea_scrolledwin,
                XmNheight, 130,
                XmNwidth, 400,
                NULL);
    }
    if (instance->module_drawarea == NULL)
        return -1;

    
    /*
     * Call user (Post-)Create procs
     */
    projP_set_userdata(instance->module_drawarea, (XtPointer)NULL, (XtPointer)instance);
    return 0;
}



